:root {
  color-scheme: dark;
  --paper: #0d1117;
  --surface: #151b23;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --green: #5eead4;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --display: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  min-width: 320px;
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.65 var(--sans);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; }
a:focus-visible { outline: 3px solid #fb923c; outline-offset: 4px; }

.skip-link {
  position: fixed;
  z-index: 5;
  top: 12px;
  left: 12px;
  padding: 9px 13px;
  transform: translateY(-160%);
  background: var(--ink);
  color: #0d1117;
  text-decoration: none;
}
.skip-link:focus { transform: translateY(0); }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; clip-path: inset(50%); }

.page-shell { width: min(1120px, calc(100% - 72px)); margin: 0 auto; }
.site-header { display: flex; min-height: 78px; align-items: center; justify-content: space-between; gap: 24px; border-bottom: 1px solid var(--line); }
.wordmark { color: var(--ink); font-size: 1.15rem; font-weight: 850; letter-spacing: -.09em; text-decoration: none; }
.wordmark span { color: var(--green); }
.site-nav { display: flex; gap: 34px; color: var(--muted); font-size: .79rem; }
.site-nav a, .header-link { text-decoration: none; transition: color 160ms ease; }
.site-nav a:hover, .header-link:hover, .text-link:hover { color: var(--green); }
.header-link { color: var(--ink); font-size: .77rem; font-weight: 700; }
.header-link span { margin-left: 6px; color: var(--green); }

.hero { display: grid; min-height: 545px; grid-template-columns: minmax(0, 1fr) 370px; align-items: center; gap: 90px; padding: 70px 0 74px; }
.hero-copy { max-width: 620px; }
.eyebrow { margin: 0 0 20px; color: #9aa5b4; font-size: .65rem; font-weight: 750; letter-spacing: .12em; }
.status-dot { display: inline-block; width: 7px; height: 7px; margin: 0 7px 1px 0; border-radius: 50%; background: #86efac; }
.eyebrow-divider { margin: 0 7px; color: #6b7686; }
h1, h2, h3, p { margin-top: 0; }
h1, h2, h3 { font-family: var(--display); }
h1 { max-width: 640px; margin-bottom: 23px; font-size: clamp(3.55rem, 7vw, 5.85rem); font-weight: 650; letter-spacing: -.075em; line-height: 1.02; }
h1 span { color: var(--green); }
.hero-intro { max-width: 475px; margin-bottom: 27px; color: var(--muted); font-size: .98rem; line-height: 1.85; }
.hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 23px; }
.button { display: inline-flex; min-height: 46px; align-items: center; justify-content: center; gap: 16px; padding: 0 17px; font-size: .77rem; font-weight: 700; text-decoration: none; transition: transform 160ms ease, background 160ms ease; }
.button:hover { transform: translateY(-2px); }
.button-dark { background: var(--ink); color: #0d1117; }
.button-dark:hover { background: var(--green); }
.button-dark span { font-size: 1rem; }
.text-link { color: var(--ink); font-size: .78rem; font-weight: 650; text-decoration: none; }
.text-link span { margin-left: 5px; color: var(--green); }
.hero-meta { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 39px; color: #9aa5b4; font-size: .7rem; }
.hero-meta a { color: #e8edf3; text-decoration: none; }
.hero-meta a:hover { color: var(--green); }
.hero-meta a span:first-child { margin-left: 3px; color: var(--green); }
.meta-separator { color: #6b7686; }

.portrait-wrap { position: relative; width: 100%; max-width: 345px; justify-self: end; }
.portrait-frame { height: 410px; overflow: hidden; background: #2b3645; }
.portrait-frame img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center 27%; }
.portrait-note { position: absolute; right: -24px; bottom: 38px; padding: 11px 13px; background: var(--surface); color: #9aa5b4; font-size: .55rem; font-weight: 750; letter-spacing: .1em; }
.portrait-note span { padding: 0 3px; color: #6b7686; }
.portrait-index { position: absolute; top: -25px; right: 0; color: #6b7686; font-size: .62rem; letter-spacing: .08em; }

.section { padding: 83px 0 0; }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 28px; margin-bottom: 27px; }
.section-heading .eyebrow { margin-bottom: 10px; }
h2 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 600; letter-spacing: -.065em; line-height: 1.1; }
.section-heading h2 { max-width: 620px; margin-bottom: 0; }
.section-note { max-width: 255px; margin: 0 0 5px; color: var(--muted); font-size: .76rem; }
.about-section .section-heading, .approach-section .section-heading { align-items: flex-start; }
.about-copy { max-width: 475px; }
.about-copy p { margin: 0 0 13px; color: var(--muted); font-size: .84rem; line-height: 1.9; }
.about-copy p:last-child { margin-bottom: 0; }
.project-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 36px; }
.project-card { min-width: 0; padding: 17px 0 20px; border-top: 1px solid var(--line); }
.project-card-top { display: flex; align-items: center; justify-content: space-between; color: #9aa5b4; font-size: .58rem; font-weight: 750; letter-spacing: .1em; }
.project-category span { padding: 0 4px; color: #6b7686; }
.project-number { color: #6b7686; font-size: .61rem; }
.project-details { display: flex; min-height: 130px; align-items: flex-start; flex-direction: column; justify-content: space-between; gap: 15px; padding-top: 27px; }
.project-details h3 { margin: 0 0 8px; font-size: 1.3rem; font-weight: 650; letter-spacing: -.04em; }
.project-details p { max-width: 310px; margin: 0; color: var(--muted); font-size: .72rem; line-height: 1.65; }
.project-link { display: inline-flex; flex: 0 0 auto; align-items: center; gap: 9px; color: var(--green); font-size: .67rem; font-weight: 700; text-decoration: none; }
.project-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.project-link > span[aria-hidden] { font-size: .9rem; }

.experience-list { border-top: 1px solid var(--line); }
.experience-row { display: grid; grid-template-columns: 190px minmax(190px, 1fr) minmax(200px, .92fr); align-items: center; gap: 25px; padding: 24px 5px; border-bottom: 1px solid var(--line); }
.experience-date { margin: 0; color: #9aa5b4; font-size: .61rem; font-weight: 700; letter-spacing: .07em; }
.experience-date span { padding: 0 3px; color: #6b7686; }
.experience-role h3 { margin: 0 0 1px; font-size: 1rem; font-weight: 650; letter-spacing: -.025em; }
.experience-role p { margin: 0; color: var(--green); font-size: .71rem; font-weight: 650; }
.experience-summary { max-width: 330px; margin: 0; color: var(--muted); font-size: .71rem; }

.skill-groups { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.skill-group { padding: 21px 22px 23px 0; }
.skill-group + .skill-group { padding-left: 22px; border-left: 1px solid var(--line); }
.skill-group h3 { margin: 0 0 9px; font-size: .87rem; font-weight: 700; }
.skill-group p { max-width: 300px; margin: 0; color: var(--muted); font-size: .72rem; line-height: 1.9; }

.contact-panel { margin-top: 89px; padding: 30px 32px 32px; border: 1px solid #263040; background: #322c1a; }
.contact-panel .eyebrow { margin-bottom: 16px; }
.contact-row { display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.contact-row h2 { margin: 0; font-size: clamp(1.7rem, 4vw, 2.6rem); }
.contact-link { display: inline-flex; flex: 0 0 auto; align-items: center; gap: 10px; padding-bottom: 5px; border-bottom: 1px solid #3a4658; color: #86efac; font-size: .76rem; font-weight: 700; text-decoration: none; }
.contact-link:hover { border-color: var(--ink); color: var(--ink); }

.site-footer { display: flex; min-height: 81px; align-items: center; justify-content: space-between; gap: 18px; color: #9aa5b4; font-size: .62rem; }
.site-footer a { text-decoration: none; }
.site-footer a:hover { color: var(--green); }
.footer-home { color: #e8edf3; font-weight: 700; }
.footer-home span { margin-left: 5px; color: var(--green); }
.site-footer > span { font-size: .53rem; font-weight: 700; letter-spacing: .08em; }
.site-footer > span span { padding: 0 3px; color: var(--green); }

@media (max-width: 850px) {
  .page-shell { width: min(100% - 48px, 700px); }
  .hero { grid-template-columns: minmax(0, 1fr) 280px; gap: 38px; }
  .portrait-frame { height: 360px; }
  .project-details { align-items: flex-start; flex-direction: column; gap: 11px; }
  .experience-row { grid-template-columns: 145px minmax(165px, 1fr) minmax(150px, .85fr); gap: 16px; }
}

@media (max-width: 620px) {
  .page-shell { width: min(100% - 34px, 500px); }
  .site-header { min-height: 68px; gap: 13px; }
  .site-nav { gap: 15px; font-size: .67rem; }
  .header-link { font-size: .68rem; }
  .hero { grid-template-columns: 1fr; gap: 34px; padding: 54px 0 49px; }
  .hero-copy { order: 1; }
  .portrait-wrap { width: min(78%, 310px); justify-self: center; }
  .portrait-frame { height: 340px; }
  .portrait-note { right: -16px; bottom: 24px; font-size: .5rem; }
  .portrait-index { top: -20px; }
  .eyebrow { font-size: .57rem; }
  h1 { font-size: clamp(3.25rem, 15vw, 4.7rem); }
  .hero-intro { font-size: .87rem; }
  .hero-meta { margin-top: 28px; font-size: .66rem; }
  .section { padding-top: 63px; }
  .section-heading { align-items: flex-start; flex-direction: column; gap: 10px; margin-bottom: 20px; }
  .section-heading h2 { font-size: 2.35rem; }
  .section-note { max-width: 340px; }
  .project-grid { grid-template-columns: 1fr; gap: 13px; }
  .project-details { min-height: auto; }
  .experience-row { grid-template-columns: 1fr 1fr; gap: 8px 13px; padding: 19px 3px; }
  .experience-date { grid-column: 1 / -1; }
  .experience-summary { grid-column: 1 / -1; }
  .skill-groups { grid-template-columns: 1fr; }
  .skill-group { padding: 16px 0; }
  .skill-group + .skill-group { padding-left: 0; border-top: 1px solid var(--line); border-left: 0; }
  .contact-panel { margin-top: 64px; padding: 23px 19px; }
  .contact-row { align-items: flex-start; flex-direction: column; gap: 17px; }
  .contact-row h2 { font-size: 2rem; }
  .site-footer { min-height: 76px; flex-wrap: wrap; gap: 8px 17px; padding: 15px 0; }
  .site-footer > span { width: 100%; }
}

@media (max-width: 400px) {
  .site-header { gap: 8px; }
  .site-nav { gap: 9px; font-size: .61rem; }
  .header-link { font-size: .63rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; }
}

h2 {
  color: #15803d;
}

p {
  font-family: Georgia, serif;
}

:root {
  color-scheme: dark;
  --page: #0d1117;
  --surface: #151b23;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --accent: #5eead4;
  --accent-soft: #12302f;
  --warm: #fb923c;
}
@media (prefers-color-scheme: dark) {
  :root { --page: #0d1117; --surface: #151b23; --ink: #e8edf3; --muted: #9aa5b4; --line: #263040; --accent: #5eead4; --accent-soft: #12302f; --warm: #fb923c; }
}
* { box-sizing: border-box; }
body { margin: 0; padding: 30px 18px 56px; background: repeating-linear-gradient(135deg, transparent 0 36px, rgb(94 234 212 / 3%) 36px 37px), var(--page); color: var(--ink); font: 16px/1.6 "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; }
main { width: min(100%, 880px); margin: 0 auto; }
a { color: var(--accent); text-underline-offset: 3px; }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 3px solid var(--warm); outline-offset: 3px; }
.back { display: inline-block; margin-bottom: 22px; font-weight: 700; }
.eyebrow { margin: 0 0 6px; color: var(--accent); font-size: .76rem; font-weight: 800; text-transform: uppercase; }
h1, h2 { font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-weight: 500; line-height: 1.2; }
h1 { margin: 0 0 12px; font-size: clamp(2rem, 5vw, 3.1rem); }
h2 { margin: 0 0 10px; font-size: 1.45rem; }
.lede { max-width: 68ch; margin: 0 0 24px; color: var(--muted); }
.panel { margin: 18px 0; padding: 22px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
.controls { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 14px 0; }
button { min-height: 42px; padding: 9px 15px; border: 1px solid var(--accent); border-radius: 5px; background: var(--accent); color: #0d1117; font: inherit; font-weight: 700; cursor: pointer; }
button.secondary { background: transparent; color: var(--accent); }
input, textarea { width: min(100%, 420px); min-height: 42px; padding: 9px 11px; border: 1px solid var(--line); border-radius: 5px; background: var(--surface); color: var(--ink); font: inherit; }
textarea { min-height: 90px; resize: vertical; }
.output { min-height: 34px; margin: 12px 0 0; color: var(--muted); }
.demo-box { padding: 16px; border: 1px solid var(--line); border-radius: 5px; background: var(--page); }
.highlight { background: #32251a; color: #e8edf3; }
.dark-card { background: #10151c; color: #6b7686; }
.list { display: grid; gap: 8px; margin: 12px 0 0; padding: 0; list-style: none; }
.list li { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 5px; }
.list [hidden] { display: none; }
.list li button { min-height: 34px; padding: 5px 10px; }
code, pre { font-family: ui-monospace, SFMono-Regular, "JetBrains Mono", Consolas, monospace; }
pre { overflow-x: auto; padding: 14px; border-radius: 5px; background: var(--page); font-size: .9rem; }
.tree { padding: 14px 18px; border-left: 2px solid var(--accent); background: var(--page); font-family: ui-monospace, SFMono-Regular, "JetBrains Mono", Consolas, monospace; white-space: pre-wrap; }
small, .muted { color: var(--muted); }
@media (max-width: 520px) { body { padding: 22px 12px 40px; } .panel { padding: 17px; } }

:root {
  color-scheme: dark;
  --page: #0d1117;
  --surface: #151b23;
  --surface-soft: #1b232d;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --accent: #5eead4;
  --accent-dark: #99f6e4;
  --accent-soft: #12302f;
  --warm: #fb923c;
  --danger: #f87171;
  --shadow: 0 16px 44px rgb(0 0 0 / 38%);
}

@media (prefers-color-scheme: dark) {
  :root {
    --page: #0d1117;
    --surface: #151b23;
    --surface-soft: #1b232d;
    --ink: #e8edf3;
    --muted: #9aa5b4;
    --line: #263040;
    --accent: #5eead4;
    --accent-dark: #99f6e4;
    --accent-soft: #12302f;
    --warm: #fb923c;
    --danger: #f87171;
    --shadow: 0 16px 44px rgb(0 0 0 / 38%);
  }
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 36px 20px 64px;
  background: radial-gradient(ellipse at 8% 5%, rgb(167 139 250 / 14%), transparent 32rem),
    radial-gradient(ellipse at 96% 34%, rgb(251 146 60 / 13%), transparent 28rem),
    var(--page);
  color: var(--ink);
  font: 16px/1.6 "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

main { width: min(100%, 960px); margin: 0 auto; }

a { color: var(--accent-dark); text-underline-offset: 4px; }
a:hover { color: var(--warm); }
a:focus-visible, button:focus-visible, input:focus-visible { outline: 3px solid var(--warm); outline-offset: 3px; }

.back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 32px;
  font-size: .92rem;
  font-weight: 700;
  text-decoration: none;
}

.back::before { content: "←"; font-size: 1.1em; }

.eyebrow {
  margin: 0 0 8px;
  color: var(--accent-dark);
  font-size: .75rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1, h2 { font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-weight: 500; line-height: 1.15; }
h1 { margin: 0 0 14px; font-size: clamp(2.5rem, 7vw, 4.5rem); letter-spacing: -.045em; }
h2 { margin: 0; font-size: clamp(1.45rem, 4vw, 2rem); }

.lede { max-width: 62ch; margin: 0 0 32px; color: var(--muted); font-size: 1.08rem; }
.panel { padding: clamp(20px, 4vw, 34px); border: 1px solid var(--line); border-radius: 20px; background: var(--surface); box-shadow: var(--shadow); }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin-bottom: 20px; }
.section-heading .eyebrow { margin-bottom: 5px; }
.sample-count { padding: 7px 12px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); font-size: .78rem; font-weight: 700; white-space: nowrap; }
.sample-list { display: grid; gap: 12px; margin: 0; padding: 0; list-style: none; }
.sample-list a { display: grid; grid-template-columns: 46px 1fr auto; align-items: center; gap: 16px; padding: 17px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-soft); color: var(--ink); text-decoration: none; transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease; }
.sample-list a:hover { transform: translateY(-2px); border-color: var(--accent); box-shadow: 0 8px 24px rgb(0 0 0 / 24%); }
.sample-number { display: grid; width: 42px; height: 42px; place-items: center; border-radius: 12px; background: var(--accent-soft); color: var(--accent-dark); font-size: .8rem; font-weight: 800; }
.sample-list strong, .sample-list small { display: block; }
.sample-list strong { font-size: 1.02rem; }
.sample-list small { margin-top: 3px; color: var(--muted); font-size: .88rem; }
.sample-arrow { color: var(--accent); font-size: 1.2rem; }
.page-note { margin: 20px 4px 0; color: var(--muted); font-size: .9rem; }

.counter-panel { max-width: 620px; margin: 28px auto 0; text-align: center; }
.counter-icon { display: grid; width: 58px; height: 58px; margin: 0 auto 18px; place-items: center; border-radius: 18px; background: var(--accent-soft); color: var(--accent-dark); font-size: 1.7rem; }
.counter-panel h1 { font-size: clamp(2rem, 6vw, 3rem); }
.counter-label { margin: 24px 0 0; color: var(--muted); font-size: .9rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.counter-value { display: block; margin: 0 0 24px; color: var(--accent-dark); font-size: clamp(4.5rem, 16vw, 7rem); font-weight: 800; line-height: 1.15; font-variant-numeric: tabular-nums; }
.controls { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; }
button { min-height: 46px; padding: 10px 18px; border: 1px solid var(--accent); border-radius: 12px; background: var(--accent); color: #0d1117; font: inherit; font-weight: 750; cursor: pointer; transition: transform .18s ease, background .18s ease; }
button:hover { transform: translateY(-2px); background: var(--accent-dark); }
button.secondary { background: var(--surface); color: var(--accent-dark); }
button.secondary:hover { background: var(--accent-soft); }
button.reset { border-color: var(--line); background: var(--surface); color: var(--danger); }
button.reset:hover { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 8%, var(--surface)); }
.counter-hint { margin: 18px 0 0; color: var(--muted); font-size: .85rem; }

.basics-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.basics-grid .panel { min-width: 0; padding: 22px; }
.basics-grid h2 { margin-bottom: 8px; font-family: inherit; font-size: 1.08rem; font-weight: 750; }
.lesson-number { margin: 0 0 8px; color: var(--accent); font-size: .72rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.lesson-copy { margin: 0 0 14px; color: var(--muted); font-size: .9rem; }
.field-label { display: block; margin: 12px 0 5px; font-size: .88rem; font-weight: 700; }
input { width: 100%; min-height: 44px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface-soft); color: var(--ink); font: inherit; }
.basics-grid button { min-height: 40px; margin-top: 10px; padding: 8px 14px; border-radius: 10px; font-size: .9rem; }
.output { min-height: 28px; margin: 13px 0 0; color: var(--muted); font-size: .9rem; overflow-wrap: anywhere; }
.output:empty { min-height: 0; margin-top: 0; }
.code-output { white-space: pre-line; }
.success { color: var(--accent-dark); font-weight: 700; }

@media (max-width: 640px) {
  body { padding: 24px 14px 42px; }
  .back { margin-bottom: 26px; }
  .basics-grid { grid-template-columns: 1fr; }
}

@media (max-width: 420px) {
  .sample-list a { grid-template-columns: 40px 1fr auto; gap: 11px; padding: 13px; }
  .sample-number { width: 38px; height: 38px; }
  .section-heading { align-items: flex-start; flex-direction: column; }
  .counter-panel .controls { display: grid; grid-template-columns: 1fr 1fr; }
