}
input::placeholder, textarea::placeholder { color: var(--muted); opacity: .8; }
input:not([type="checkbox"]):not([type="range"]):focus, select:focus, textarea:focus { border-color: var(--accent); outline: 0; box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 15%, transparent); }
