@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

:root {
  color-scheme: dark;
  --page: #0d1117;
  --surface: #151b23;
  --surface-soft: #1b232d;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --accent: #5eead4;
  --accent-dark: #99f6e4;
  --accent-soft: #12302f;
  --orange: #a78bfa;
  --blue: #1a2232;
  --danger: #f87171;
  --success: #86efac;
  --shadow: 0 24px 70px rgb(0 0 0 / 38%);
}

@media (prefers-color-scheme: dark) {
  :root {
    --page: #0d1117;
    --surface: #151b23;
    --surface-soft: #1b232d;
    --ink: #e8edf3;
    --muted: #9aa5b4;
    --line: #263040;
    --accent: #5eead4;
    --accent-dark: #99f6e4;
