.lab-symbol { display: grid; width: 39px; height: 39px; place-items: center; border: 1px solid var(--line); border-radius: 13px; background: var(--surface); color: var(--accent); font-size: 1.3rem; }
.lab-title { max-width: 24ch; font-size: 1.04rem; font-weight: 800; line-height: 1.3; }
.lab-description { max-width: 40ch; margin-top: 7px; color: var(--muted); font-size: .82rem; line-height: 1.5; }
.lab-action { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 12px; margin-top: auto; padding-top: 21px; color: var(--accent); font-size: .78rem; font-weight: 800; }
.lab-action span { font-size: 1.15rem; }
.lab-card-lime .lab-symbol { background: var(--accent-soft); }
.lab-card-violet .lab-symbol { color: var(--orange); background: color-mix(in srgb, var(--orange) 12%, var(--surface)); }
