.lab-card-quiet:hover { background: var(--surface-soft); }
.lab-card-quiet .lab-symbol { color: var(--muted); }
.lab-card-quiet .lab-action { color: var(--muted); }
.page-note > span { margin-right: 5px; color: var(--accent); }

.lesson-page { width: min(100%, 860px); margin: 0 auto; }
.lesson-heading { max-width: 680px; margin: 0 auto 29px; text-align: center; }
.lesson-heading .eyebrow { margin-bottom: 8px; }
.lesson-heading h1 { margin-bottom: 10px; font-size: clamp(2.3rem, 7vw, 4rem); }
.lesson-heading h1 span { color: var(--accent); font-style: normal; }
.lesson-heading > p:last-child { max-width: 58ch; margin: 0 auto; color: var(--muted); }
.demo-card, .signup-layout, .signup-success { border: 1px solid var(--line); border-radius: 20px; background: var(--surface); box-shadow: var(--shadow); }
.demo-card { padding: clamp(21px, 5vw, 38px); }
.demo-kicker { margin: 0 0 6px; color: var(--accent); font-size: .72rem; font-weight: 850; letter-spacing: .12em; text-transform: uppercase; }
.demo-card h2, .signup-main h2 { font-size: clamp(1.35rem, 4vw, 1.8rem); }
.demo-copy { margin: 8px 0 22px; color: var(--muted); font-size: .91rem; }
.preview-window { overflow: hidden; border: 1px solid var(--line); border-radius: 15px; background: #0d1117; }
.preview-bar { display: flex; align-items: center; gap: 6px; padding: 12px 14px; border-bottom: 1px solid var(--line); color: var(--muted); font-size: .72rem; }
.preview-dot { width: 8px; height: 8px; border-radius: 50%; background: #f87171; }
.preview-dot:nth-child(2) { background: #fb923c; }
.preview-dot:nth-child(3) { margin-right: 8px; background: #86efac; }
.preview-content { padding: clamp(20px, 5vw, 34px); }
.preview-content h3 { margin: 0; font-size: 1.12rem; }
.preview-content > p { margin: 6px 0 20px; color: var(--muted); font-size: .84rem; }
.preview-actions { display: flex; align-items: center; gap: 12px; }
.primary-action, .icon-action, .signup-submit, .signup-reset { min-height: 44px; border: 0; border-radius: 10px; font: inherit; font-size: .85rem; font-weight: 800; cursor: pointer; transition: transform .18s ease, background .18s ease; }
.primary-action, .signup-submit { padding: 10px 16px; background: var(--accent); color: #0d1117; }
.primary-action:hover, .signup-submit:hover { transform: translateY(-2px); background: #86efac; }
.icon-action { display: grid; width: 44px; place-items: center; border: 1px solid var(--line); background: var(--surface-soft); color: var(--ink); font-size: 1.1rem; }
.icon-action:hover { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 12%, var(--surface)); }
.activation-result { min-height: 24px; margin: 17px 0 0; color: var(--accent); font-size: .82rem; font-weight: 650; }
.takeaway { display: grid; grid-template-columns: 38px 1fr; gap: 12px; align-items: start; margin-top: 16px; padding: 16px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-soft); }
.takeaway-mark { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 11px; background: var(--accent-soft); color: var(--accent); font-weight: 850; }
.takeaway strong { display: block; margin: 1px 0 2px; font-size: .84rem; }
.takeaway p { margin: 0; color: var(--muted); font-size: .79rem; }
.image-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 13px; margin-top: 21px; }
.image-example { overflow: hidden; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-soft); }
.image-example figure { margin: 0; }
.image-frame { display: grid; min-height: 150px; place-items: center; overflow: hidden; background: #151b23; }
.image-frame img { display: block; max-width: 100%; max-height: 180px; object-fit: cover; }
.image-example figcaption { padding: 12px 14px 14px; color: var(--muted); font-size: .77rem; line-height: 1.5; }
.image-example figcaption strong { display: block; margin-bottom: 3px; color: var(--ink); font-size: .83rem; }
.image-example figcaption code { color: var(--accent); font-size: .73rem; }
.image-example .wave-frame img { width: 100%; height: 80px; object-fit: cover; }
.image-example .logo-frame img { width: 170px; height: 105px; object-fit: contain; }
.image-example .chart-frame img { width: 100%; }
.alt-check { display: flex; align-items: center; justify-content: space-between; gap: 15px; margin-top: 20px; padding: 15px; border: 1px solid var(--line); border-radius: 13px; background: var(--surface-soft); }
.alt-check p { margin: 0; color: var(--muted); font-size: .8rem; }
.alt-check-button { flex: 0 0 auto; min-height: 42px; padding: 9px 14px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); color: var(--ink); font: inherit; font-size: .78rem; font-weight: 800; cursor: pointer; }
.alt-check-button:hover { border-color: var(--accent); color: var(--accent); }
.alt-results { margin-top: 12px; }
.alt-results:empty { display: none; }
.alt-results ul { display: grid; gap: 7px; margin: 0; padding: 0; list-style: none; }
.alt-results li { display: flex; align-items: flex-start; gap: 9px; padding: 10px 12px; border-radius: 9px; background: var(--accent-soft); color: var(--ink); font-size: .78rem; line-height: 1.45; }
.alt-results li[data-status="error"] { background: color-mix(in srgb, var(--danger) 12%, var(--surface)); }
.alt-results strong { flex: 0 0 auto; color: var(--accent); font-size: .7rem; letter-spacing: .06em; }
.alt-results li[data-status="error"] strong { color: var(--danger); }
.signup-layout { display: grid; grid-template-columns: .8fr 1.2fr; overflow: hidden; }
.signup-aside { display: flex; flex-direction: column; align-items: flex-start; justify-content: space-between; padding: clamp(25px, 5vw, 38px); background: linear-gradient(150deg, #201a32, #1a3223); }
.signup-aside h2 { max-width: 9ch; margin: 10px 0; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: clamp(2rem, 5vw, 2.8rem); font-weight: 500; line-height: 1.1; }
.signup-aside > p:last-child { margin: 0; color: #8fb4ff; font-size: .85rem; }
.signup-mark { display: grid; width: 48px; height: 48px; place-items: center; border: 1px solid rgb(86 99 119 / 15%); border-radius: 15px; background: rgb(255 255 255 / 1%); color: var(--accent); font-size: 1.3rem; }
.signup-main { padding: clamp(23px, 5vw, 38px); }
.signup-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.signup-top .eyebrow { margin-bottom: 5px; }
.signup-main h2 { margin: 0; }
.icon-button { display: grid; width: 42px; height: 42px; flex: 0 0 auto; place-items: center; border: 1px solid var(--line); border-radius: 12px; background: var(--surface-soft); color: var(--ink); font-size: 1.15rem; cursor: pointer; }
.search-feedback { margin: 10px 0 0; color: var(--accent); font-size: .78rem; }
.signup-intro { margin: 7px 0 21px; color: var(--muted); font-size: .84rem; }
.signup-field { margin-bottom: 15px; }
.signup-field label { display: block; margin-bottom: 6px; font-size: .8rem; font-weight: 750; }
.signup-field input { width: 100%; min-height: 45px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-soft); color: var(--ink); font: inherit; font-size: .84rem; }
.signup-field input::placeholder { color: var(--muted); }
.signup-field input[aria-invalid="true"] { border-color: var(--danger); }
.signup-field input[aria-invalid="false"]:focus { border-color: var(--accent); }
.signup-hint { margin: 5px 0 0; color: var(--muted); font-size: .72rem; }
.signup-error { min-height: 0; margin: 0; color: var(--danger); font-size: .73rem; }
.signup-error:not(:empty) { min-height: 18px; margin-top: 4px; }
.signup-submit { width: 100%; margin-top: 5px; }
.signup-result { margin: 12px 0 0; color: var(--accent); font-size: .8rem; }
.signup-logo-link { display: inline-flex; align-items: center; gap: 10px; margin-top: 21px; color: var(--muted); font-size: .72rem; text-decoration: none; }
.signup-logo-link img { display: block; width: 38px; height: 38px; border-radius: 10px; }

@media (max-width: 760px) {
  body { padding: 24px 14px 42px; }
  .hero { grid-template-columns: 1fr; gap: 24px; }
  .hero-art { min-height: 245px; }
  .lesson-grid { grid-template-columns: 1fr; }
  .lesson { display: grid; grid-template-columns: 38px 1fr; column-gap: 12px; align-items: center; }
  .lesson-icon { grid-row: span 2; margin: 0; }
  .lesson p { margin-top: 2px; }
  .form-layout { grid-template-columns: 1fr; }
  .form-aside { min-height: 235px; }
  .aside-bottom { margin-top: 30px; }
  .signup-layout { grid-template-columns: 1fr; }
  .signup-aside { min-height: 220px; }
}

@media (max-width: 480px) {
  .section-heading { align-items: flex-start; flex-direction: column; }
  .field-row { grid-template-columns: 1fr; gap: 0; }
  .form-main { padding: 23px 18px; }
  .lab-row { grid-template-columns: 38px minmax(0, 1fr) auto; gap: 10px; padding: 12px; }
  .lab-copy small { font-size: .72rem; }
  .summary-row { flex-direction: column; gap: 2px; }
  .summary-row dd { text-align: left; }
  .lab-grid, .image-grid { grid-template-columns: 1fr; }
  .lab-card { min-height: 205px; }
  .alt-check { align-items: flex-start; flex-direction: column; }
  .preview-actions { align-items: stretch; }
  .primary-action { flex: 1; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap");

:root {
  color-scheme: dark;
  --paper: #0d1117;
  --surface: #151b23;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --green: #5eead4;
  --green-soft: #12302f;
  --violet: #a78bfa;
  --amber: #fb923c;
  --blue: #5eead4;
  --mono: ui-monospace, SFMono-Regular, "JetBrains Mono", Consolas, monospace;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  min-width: 320px;
  margin: 0;
  background: radial-gradient(ellipse at 82% 5%, rgb(251 191 36 / 16%), transparent 34rem),
    var(--paper);
  color: var(--ink);
  font: 15px/1.65 var(--sans);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; }
a:focus-visible, summary:focus-visible {
  outline: 3px solid #86efac;
  outline-offset: 4px;
  border-radius: 3px;
}

.skip-link {
  position: fixed;
  z-index: 5;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  transform: translateY(-160%);
  border-radius: 5px;
  background: #86efac;
  color: #0d1117;
  font-weight: 700;
}

.skip-link:focus { transform: translateY(0); }

.report-shell { width: min(100% - 64px, 1120px); margin: 0 auto; }

.topbar {
  display: flex;
  min-height: 73px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid #263040;
  font-size: .75rem;
}

.wordmark { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; font-size: .74rem; font-weight: 700; letter-spacing: .13em; }
.wordmark-icon { display: grid; width: 29px; height: 29px; place-items: center; border-radius: 8px; background: var(--green); color: #0d1117; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 1.15rem; letter-spacing: 0; }
.wordmark-light { color: #9aa5b4; font-weight: 500; }
.top-links { display: flex; align-items: center; gap: 11px; color: #6b7686; }
.top-links a { text-decoration: none; transition: color .18s ease; }
.top-links a:hover, .footer a:hover { color: var(--green); }
.top-links [aria-current="page"] { color: var(--ink); font-weight: 600; }
.report-status { display: inline-flex; align-items: center; gap: 8px; color: #9aa5b4; font-family: var(--mono); font-size: .62rem; letter-spacing: .08em; }
.report-status span { width: 7px; height: 7px; border-radius: 50%; background: #86efac; box-shadow: 0 0 0 3px rgb(0 0 0 / 40%); }

.hero {
  position: relative;
  display: grid;
  min-height: 420px;
  grid-template-columns: minmax(0, 1.15fr) minmax(300px, .75fr);
  align-items: center;
  gap: 70px;
  padding: 76px 50px 70px 52px;
  border-bottom: 1px solid var(--line);
}

.hero-copy { position: relative; z-index: 1; }
.eyebrow { margin: 0 0 15px; color: #9aa5b4; font-family: var(--mono); font-size: .65rem; font-weight: 500; letter-spacing: .105em; }
.eyebrow-divider { margin: 0 7px; color: #fb923c; }
h1, h2, h3, p { margin-top: 0; }
h1, h2 { font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-weight: 500; }
h1 { margin-bottom: 18px; font-size: clamp(3rem, 6vw, 4.65rem); letter-spacing: -.055em; line-height: 1.08; }
h1 em { color: var(--green); font-weight: 500; }
.hero-intro { max-width: 480px; margin-bottom: 26px; color: #9aa5b4; font-size: .96rem; line-height: 1.8; }
.report-meta { display: flex; align-items: center; gap: 11px; }
.meta-avatar { display: grid; width: 37px; height: 37px; place-items: center; border: 1px solid #263040; border-radius: 50%; background: #322c1a; color: #86efac; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 1rem; }
.report-meta strong, .report-meta small { display: block; }
.report-meta strong { font-size: .76rem; font-weight: 700; line-height: 1.35; }
.report-meta small { margin-top: 2px; color: #9aa5b4; font-size: .65rem; }
.meta-separator { height: 27px; margin: 0 4px; border-left: 1px solid #263040; }
.meta-label { color: #9aa5b4; font-family: var(--mono); font-size: .6rem; letter-spacing: .07em; }

.hero-summary { position: relative; z-index: 1; padding: 23px 24px 18px; border: 1px solid #2b3a4a; border-radius: 8px; background: rgb(21 27 35 / 75%); box-shadow: 0 14px 35px rgb(0 0 0 / 18%); }
.summary-top, .summary-foot { display: flex; align-items: center; justify-content: space-between; }
.summary-label { color: #9aa5b4; font-family: var(--mono); font-size: .62rem; letter-spacing: .1em; }
.summary-mark { display: grid; width: 25px; height: 25px; place-items: center; border-radius: 50%; background: var(--green-soft); color: var(--green); font-size: .9rem; }
.score-change { display: flex; align-items: center; justify-content: center; gap: 22px; padding: 27px 0 18px; }
.score { display: flex; flex-direction: column; align-items: center; gap: 1px; }
.score strong { font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 3.45rem; font-weight: 500; letter-spacing: -.06em; line-height: 1.15; }
.score span { color: #6b7686; font-family: var(--mono); font-size: .57rem; letter-spacing: .11em; }
.score-before strong { color: #fb923c; }
.score-after strong { color: var(--green); }
.score-arrow { color: #6b7686; font-size: 1.35rem; }
.summary-note { margin: 0; color: #9aa5b4; font-family: var(--mono); font-size: .62rem; text-align: center; }
.summary-rule { margin: 19px 0 12px; border-top: 1px solid #2b3a4a; }
.summary-foot { color: #9aa5b4; font-size: .66rem; }
.pass-mark { color: var(--green); font-weight: 700; }
.hero-index { position: absolute; right: 3px; bottom: 17px; color: #6b7686; font-family: var(--mono); font-size: .61rem; letter-spacing: .08em; }
.hero-index span { color: #6b7686; }

.overview { padding: 35px 52px 32px; border-bottom: 1px solid var(--line); }
.overview-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.overview-heading .eyebrow { margin: 0; }
.overview-heading > p:last-child { margin: 0; color: #9aa5b4; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: .95rem; font-style: italic; }
.stat-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.stat { min-height: 115px; padding: 15px 16px 13px; border: 1px solid #2b3a4a; border-radius: 6px; background: rgb(21 27 35 / 64%); }
.stat-icon { display: grid; width: 24px; height: 24px; margin-bottom: 9px; place-items: center; border-radius: 6px; font-size: .79rem; font-weight: 700; }
.stat-icon-green { background: #1a3223; color: #86efac; }
.stat-icon-violet { background: #222c38; color: #a78bfa; }
.stat-icon-amber { background: #32251a; color: #fb923c; }
.stat-icon-blue { background: #1a322f; color: #5eead4; }
.stat > strong { display: inline-block; margin-right: 7px; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 1.45rem; font-weight: 500; line-height: 1; }
.stat > span:last-child { color: #9aa5b4; font-size: .68rem; }

.report-nav { position: sticky; z-index: 3; top: 0; display: flex; gap: 27px; padding: 0 52px; border-bottom: 1px solid var(--line); background: #1b232d; backdrop-filter: blur(12px); }
.report-nav a { position: relative; padding: 15px 1px 13px; color: #9aa5b4; font-size: .72rem; text-decoration: none; }
.report-nav a:hover, .report-nav a.active { color: var(--green); }
.report-nav a.active { font-weight: 700; }
.report-nav a.active::after { position: absolute; right: 0; bottom: -1px; left: 0; height: 2px; background: var(--green); content: ""; }

.report-section { padding: 54px 52px 0; scroll-margin-top: 58px; }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 22px; }
.section-heading .eyebrow { margin-bottom: 7px; }
h2 { margin-bottom: 0; font-size: clamp(1.7rem, 3vw, 2.25rem); letter-spacing: -.035em; line-height: 1.2; }
.section-aside { max-width: 250px; margin: 0 0 5px; color: #9aa5b4; font-size: .68rem; text-align: right; }
.results-list { overflow: hidden; border: 1px solid #263040; border-radius: 7px; background: #151b23; }
.result-row { display: grid; min-height: 68px; grid-template-columns: 35px minmax(0, 1fr) 40px 18px 46px 91px; align-items: center; gap: 11px; padding: 10px 20px; border-bottom: 1px solid #2b3a4a; }
.result-row:last-child { border-bottom: 0; }
.result-number { color: #6b7686; font-family: var(--mono); font-size: .62rem; }
.result-page strong, .result-page code { display: block; }
.result-page strong { font-size: .75rem; font-weight: 600; }
.result-page code { margin-top: 2px; color: #6b7686; font-family: var(--mono); font-size: .59rem; }
.result-before, .result-after { font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 1.12rem; text-align: center; }
.result-before { color: #fb923c; }
.result-after { color: #86efac; font-weight: 600; }
.result-arrow { color: #6b7686; font-size: .85rem; text-align: center; }
.result-state { justify-self: end; padding: 4px 8px; border-radius: 99px; background: #222c38; color: #86efac; font-size: .61rem; font-weight: 600; }
.result-state span { margin-right: 3px; }
.results-caption { display: flex; align-items: flex-start; gap: 9px; margin: 13px 0 0; color: #9aa5b4; font-size: .68rem; line-height: 1.65; }
.caption-mark { display: grid; width: 16px; height: 16px; flex: 0 0 auto; margin-top: 1px; place-items: center; border: 1px solid #263040; border-radius: 50%; color: #9aa5b4; font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: .65rem; }

.findings-section { padding-top: 65px; }
.findings-section .section-heading { margin-bottom: 21px; }
.finding { display: grid; grid-template-columns: 42px minmax(0, 1fr); gap: 17px; padding: 22px 0; border-top: 1px solid #263040; }
.finding-number { display: grid; width: 31px; height: 31px; place-items: center; border: 1px solid #263040; border-radius: 50%; color: #9aa5b4; font-family: var(--mono); font-size: .63rem; }
.finding-heading { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; }
.finding h3 { margin: 0; font-size: .95rem; font-weight: 600; letter-spacing: -.01em; }
.audit-tag { padding: 3px 7px; border: 1px solid #2b3a4a; border-radius: 3px; color: #9aa5b4; font-family: var(--mono); font-size: .52rem; letter-spacing: .045em; }
.finding-content > p:not(.finding-meta) { max-width: 800px; margin: 7px 0 0; color: #9aa5b4; font-size: .76rem; line-height: 1.7; }
.finding-content p code { padding: 1px 4px; border-radius: 3px; background: #322c1a; color: #9aa5b4; font-family: var(--mono); font-size: .69rem; }
.finding-meta { display: flex; gap: 8px; margin: 5px 0 0; color: #6b7686; font-size: .65rem; }
.finding-meta strong { color: #9aa5b4; font-weight: 600; }
.code-disclosure { margin-top: 12px; }
.code-disclosure summary { display: flex; width: fit-content; align-items: center; gap: 9px; cursor: pointer; color: var(--green); font-size: .68rem; font-weight: 700; list-style: none; }
.code-disclosure summary::-webkit-details-marker { display: none; }
.code-disclosure summary span { color: #9aa5b4; font-size: .9rem; transition: transform .18s ease; }
.code-disclosure[open] summary span { transform: rotate(45deg); }
.code-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 11px; }
.code-panel { overflow: hidden; margin: 0; border: 1px solid #2b3a4a; border-radius: 5px; background: #151b23; }
.code-panel figcaption { display: flex; justify-content: space-between; gap: 8px; padding: 8px 11px; border-bottom: 1px solid #2b3a4a; color: #9aa5b4; font-family: var(--mono); font-size: .55rem; letter-spacing: .06em; }
.code-panel figcaption code { overflow: hidden; color: #9aa5b4; font-size: .56rem; letter-spacing: 0; text-overflow: ellipsis; white-space: nowrap; }
.code-panel pre { overflow-x: auto; margin: 0; padding: 12px; color: #9aa5b4; font: .67rem/1.65 var(--mono); white-space: pre; }
.code-after { border-color: #2b3a4a; }
.code-after figcaption { background: #1b232d; }
.code-after figcaption:first-letter { color: #86efac; }
.code-before figcaption { background: #1b232d; }

.method-card { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; align-items: center; gap: 18px; margin: 45px 52px 0; padding: 24px; border: 1px solid #2b3a4a; border-radius: 7px; background: #1a3223; scroll-margin-top: 70px; }
