@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap");

:root {
  color-scheme: dark;
  --page: #0d1117;
  --surface: #151b23;
  --surface-raised: #1b232d;
  --ink: #e8edf3;
  --muted: #9aa5b4;
  --line: #263040;
  --lime: #5eead4;
  --mono: ui-monospace, SFMono-Regular, "JetBrains Mono", Consolas, monospace;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --display: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  min-width: 320px;
  margin: 0;
  background: radial-gradient(ellipse at 87% 2%, rgb(134 239 172 / 12%), transparent 34rem),
    radial-gradient(ellipse at 9% 51%, rgb(167 139 250 / 8%), transparent 32rem),
    var(--page);
  color: var(--ink);
  font: 15px/1.6 var(--sans);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; }
a:focus-visible { outline: 3px solid var(--lime); outline-offset: 5px; border-radius: 3px; }

.skip-link {
  position: fixed;
  z-index: 5;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  transform: translateY(-160%);
  border-radius: 5px;
  background: var(--lime);
  color: #0d1117;
  font-weight: 700;
}
.skip-link:focus { transform: translateY(0); }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; clip-path: inset(50%); }

.page-shell { width: min(100% - 72px, 1160px); margin: 0 auto; }
.topbar { display: flex; min-height: 76px; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid var(--line); }
.brand { display: inline-flex; align-items: center; gap: 11px; font-size: .73rem; font-weight: 700; letter-spacing: .15em; text-decoration: none; }
.brand-mark { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 10px; background: var(--lime); color: #0d1117; font-family: var(--display); font-size: 1rem; letter-spacing: -.08em; }
.brand-light { margin-left: 4px; color: #9aa5b4; font-weight: 500; }
.top-nav { display: flex; gap: 30px; color: #e8edf3; font-size: .76rem; }
.top-nav a { text-decoration: none; transition: color .18s ease; }
.top-nav a:hover, .footer a:hover { color: var(--lime); }
.week-pill { display: inline-flex; align-items: center; gap: 8px; padding: 7px 10px; border: 1px solid #2b3a4a; border-radius: 3px; color: #e8edf3; font-family: var(--mono); font-size: .61rem; letter-spacing: .07em; }
.week-pill span { width: 6px; height: 6px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 10px rgb(0 0 0 / 60%); }

.hero { position: relative; display: grid; min-height: 540px; grid-template-columns: minmax(0, 1fr) minmax(360px, .92fr); align-items: center; gap: 64px; padding: 68px 28px 73px; border-bottom: 1px solid var(--line); }
.hero-copy { position: relative; z-index: 1; }
.eyebrow { margin: 0 0 17px; color: #e8edf3; font-family: var(--mono); font-size: .64rem; letter-spacing: .105em; }
.eyebrow-line { display: inline-block; width: 19px; margin: 0 8px 3px 0; border-top: 1px solid var(--lime); }
.eyebrow-slash { margin: 0 7px; color: var(--lime); }
h1, h2, h3, p { margin-top: 0; }
h1, h2, h3 { font-family: var(--display); }
h1 { margin-bottom: 20px; font-size: clamp(4.3rem, 8.5vw, 7.3rem); font-weight: 600; letter-spacing: -.085em; line-height: .91; }
h1 > span { color: var(--lime); }
.hero-intro { max-width: 430px; margin-bottom: 26px; color: #e8edf3; font-size: .98rem; line-height: 1.8; }
.hero-actions { display: flex; align-items: center; gap: 24px; }
.button { display: inline-flex; min-height: 45px; align-items: center; justify-content: center; gap: 16px; padding: 0 17px; border: 1px solid transparent; border-radius: 3px; font-size: .75rem; font-weight: 700; text-decoration: none; transition: transform .18s ease, background .18s ease; }
.button:hover { transform: translateY(-2px); }
.button-lime { background: var(--lime); color: #0d1117; }
.button-lime:hover { background: #86efac; }
.text-link { color: #e8edf3; font-size: .76rem; text-decoration: none; }
.text-link span[aria-hidden] { margin-left: 5px; color: var(--lime); }
.text-link:hover { color: var(--lime); }
.student-line { display: flex; align-items: center; gap: 11px; margin-top: 40px; }
.avatar { display: grid; width: 35px; height: 35px; place-items: center; border: 1px solid #3a4658; border-radius: 50%; color: var(--lime); font-family: var(--display); font-weight: 600; }
.student-line strong, .student-line small { display: block; }
.student-line strong { font-size: .76rem; }
.student-line small { margin-top: 2px; color: #9aa5b4; font-family: var(--mono); font-size: .56rem; letter-spacing: .045em; }

.hero-visual { position: relative; min-height: 350px; overflow: hidden; padding: 19px; border: 1px solid #263040; border-radius: 8px; background: linear-gradient(140deg, #151b23, #0d1117 66%); box-shadow: 0 25px 70px rgb(0 0 0 / 60%); }
.hero-visual::before { position: absolute; top: 64px; right: -66px; width: 226px; height: 226px; border: 1px solid #263040; border-radius: 50%; content: ""; }
.hero-visual::after { position: absolute; top: 83px; right: -46px; width: 186px; height: 186px; border: 1px solid #263040; border-radius: 50%; content: ""; }
.visual-top { position: relative; z-index: 1; display: flex; justify-content: space-between; color: #9aa5b4; font-family: var(--mono); font-size: .57rem; letter-spacing: .1em; }
.visual-dots { color: #6b7686; font-size: .55rem; letter-spacing: .25em; }
.flow { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; gap: 12px; padding: 53px 8px 36px; }
.flow-node { display: flex; width: 87px; height: 91px; flex-direction: column; align-items: center; justify-content: center; gap: 10px; border: 1px solid #263040; border-radius: 5px; background: #151b23; color: #e8edf3; font-family: var(--mono); font-size: .55rem; letter-spacing: .06em; }
.node-icon { color: #86efac; font-family: var(--display); font-size: 1.5rem; }
.node-branch { border-color: #a78bfa; background: #201a32; color: #a78bfa; }
.node-branch .node-icon { color: #a78bfa; }
.node-live { border-color: #86efac; background: #1a3223; color: #86efac; }
.node-live .node-icon { color: var(--lime); }
.flow-arrow { color: #6b7686; font-size: 1.1rem; }
.terminal { position: relative; z-index: 1; overflow: hidden; border: 1px solid #263040; border-radius: 5px; background: #0d1117; }
.terminal-head { display: flex; align-items: center; gap: 8px; padding: 9px 12px; border-bottom: 1px solid #263040; color: #e8edf3; font-family: var(--mono); font-size: .57rem; }
.terminal-head > span:last-child { margin-left: auto; color: #9aa5b4; }
.terminal-dot { width: 7px; height: 7px; border-radius: 50%; background: #32251a; }
.terminal code { display: block; padding: 11px 13px 13px; color: #86efac; font: .67rem/1.95 var(--mono); }
.terminal code > span:first-child, .practice-row pre span { color: var(--lime); }
.terminal-green { color: #a78bfa; }
.terminal-lime { color: #86efac; }
.visual-stamp { position: absolute; z-index: 2; top: 104px; right: 24px; display: grid; width: 61px; height: 61px; place-content: center; transform: rotate(9deg); border: 1px solid #86efac; border-radius: 50%; background: #151b23; color: var(--lime); font-family: var(--mono); font-size: .47rem; line-height: 1.25; text-align: center; }
.visual-stamp b { position: absolute; top: -5px; right: 0; font-size: .85rem; }
.hero-index { position: absolute; right: 6px; bottom: 19px; color: #9aa5b4; font-family: var(--mono); font-size: .59rem; letter-spacing: .08em; }
.hero-index span { color: #6b7686; }

.project-banner { display: flex; align-items: center; gap: 17px; margin: 25px 0 0; padding: 20px 25px; border: 1px solid #263040; border-radius: 5px; background: linear-gradient(100deg, #151b23, #151b23 57%, #151b23); }
.project-symbol { display: grid; width: 43px; height: 43px; flex: 0 0 auto; place-items: center; border: 1px solid #2b3a4a; border-radius: 50%; color: var(--lime); font-size: 1.2rem; }
.project-copy { flex: 1; }
.project-copy .eyebrow { margin-bottom: 1px; color: #86efac; font-size: .55rem; }
.project-copy h2 { margin: 0; font-size: 1.15rem; letter-spacing: -.04em; }
.project-copy p { margin: 2px 0 0; color: #9aa5b4; font-size: .73rem; }
.project-link { display: inline-flex; align-items: center; gap: 11px; padding: 10px 12px; border: 1px solid #86efac; border-radius: 3px; color: var(--lime); font-family: var(--mono); font-size: .67rem; text-decoration: none; }
.project-link:hover { background: #1a3223; }

.section { padding: 80px 28px 0; }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 28px; margin-bottom: 27px; }
.section-heading .eyebrow { margin-bottom: 10px; }
h2 { font-size: clamp(2rem, 4vw, 3.15rem); font-weight: 500; letter-spacing: -.065em; line-height: 1.04; }
.section-heading h2 { margin-bottom: 0; }
.section-note { max-width: 250px; margin: 0 0 4px; color: #9aa5b4; font-size: .75rem; line-height: 1.75; }
.tool-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 13px; }
.tool-card { position: relative; min-height: 248px; overflow: hidden; padding: 19px 20px 17px; border: 1px solid #263040; border-radius: 5px; background: var(--surface); }
.tool-card::after { position: absolute; right: -44px; bottom: -96px; width: 174px; height: 174px; border: 1px solid rgb(86 99 119 / 5%); border-radius: 50%; content: ""; }
.tool-number, .tool-tag { color: #9aa5b4; font-family: var(--mono); font-size: .56rem; letter-spacing: .08em; }
.tool-icon { display: grid; width: 37px; height: 37px; margin: 29px 0 13px; place-items: center; border: 1px solid #86efac; border-radius: 5px; color: #86efac; font-family: var(--mono); font-size: .9rem; }
.tool-card h3 { margin-bottom: 7px; font-size: 1.23rem; font-weight: 600; letter-spacing: -.04em; }
.tool-card p { max-width: 315px; margin-bottom: 18px; color: #9aa5b4; font-size: .76rem; line-height: 1.7; }
.tool-tag { color: #86efac; font-size: .52rem; }
.card-green { background: linear-gradient(145deg, #151b23, #0d1117 65%); }
.card-green .tool-icon { border-color: #86efac; background: #1a3223; color: #86efac; }
.card-violet { background: linear-gradient(145deg, #151b23, #0d1117 65%); }
.card-violet .tool-icon { border-color: #a78bfa; background: #201a32; color: #a78bfa; }
.card-violet .tool-tag { color: #a78bfa; }
.card-orange { background: linear-gradient(145deg, #151b23, #0d1117 65%); }
.card-orange .tool-icon { border-color: #fb923c; background: #32251a; color: #fb923c; }
.card-orange .tool-tag { color: #fb923c; }

.practice-section { padding-top: 91px; }
.practice-heading { margin-bottom: 23px; }
.practice-list { border-top: 1px solid var(--line); }
.practice-row { display: grid; grid-template-columns: 134px minmax(180px, 1fr) minmax(340px, .95fr); align-items: center; gap: 20px; padding: 20px 14px; border-bottom: 1px solid var(--line); transition: background .2s ease; }
.practice-row:hover { background: rgb(255 255 255 / 0%); }
