.practice-copy p { max-width: 330px; margin: 0; color: #9aa5b4; font-size: .69rem; line-height: 1.65; }
.practice-row pre { overflow-x: auto; margin: 0; padding: 10px 13px; border: 1px solid #263040; border-radius: 4px; background: #0d1117; color: #e8edf3; font: .6rem/1.85 var(--mono); }

.takeaway { display: flex; align-items: center; gap: 20px; margin: 78px 28px 0; padding: 27px 28px; border: 1px solid #2b3a4a; border-radius: 5px; background: linear-gradient(100deg, #151b23, #151b23 62%, #151b23); }
.takeaway-mark { display: grid; width: 48px; height: 48px; flex: 0 0 auto; place-items: center; border: 1px solid #86efac; border-radius: 50%; color: var(--lime); font-size: 1.25rem; }
