.takeaway h2 { margin: 0 0 3px; font-size: 1.5rem; letter-spacing: -.045em; }
.takeaway p:last-child { margin: 0; color: #9aa5b4; font-size: .71rem; }
.button-dark { min-height: 40px; flex: 0 0 auto; border-color: #86efac; color: var(--lime); }
.button-dark:hover { background: #1a3223; }
.footer { display: flex; min-height: 85px; align-items: center; justify-content: space-between; gap: 14px; margin-top: 65px; border-top: 1px solid var(--line); color: #9aa5b4; font-family: var(--mono); font-size: .55rem; letter-spacing: .04em; }
.footer a { color: #e8edf3; font-family: var(--sans); font-size: .69rem; text-decoration: none; }
