import { useState } from 'react';

function Alert({ type, message }) {
  if (!message) return null;
  return <p className={`demo-alert alert-${type}`} role="status">{message}</p>;
}

function ConditionalDemo() {
  const [user, setUser] = useState(null);

  return (
    <div className="conditional-demo">
      <Alert type="error" message={user ? '' : 'You are signed out.'} />
      <Alert type="success" message={user ? 'You are signed in.' : ''} />
      <div className="welcome-panel">
        {user && <p>Welcome back, {user.name}.</p>}
        {!user && <p>Sign in to see your dashboard.</p>}
        <button
          className="filter-button"
          type="button"
          onClick={() => setUser(user ? null : { name: 'Xushnudbek' })}
        >
          {user ? 'Sign out' : 'Sign in'}
        </button>
      </div>
    </div>
  );
}

export default ConditionalDemo;

function Greeting({ name = 'World' }) {
  return <p className="greeting">Hello, {name}!</p>;
}

export default Greeting;

function NotificationList({ notifications }) {
  return (
    <ul className="notification-list">
      {notifications.map(({ id, type, message }) => {
        const icon = type === 'success' ? '✓' : type === 'warning' ? '!' : 'i';
        return (
          <li className={`notification notification-${type}`} key={id}>
            <span className="notification-icon" aria-hidden="true">{icon}</span>
            <span>{message}</span>
          </li>
        );
      })}
    </ul>
  );
}

export default NotificationList;

function ProductCard({ name, price, rating, inStock }) {
